use hyperlane::*;

#[get]
async fn example_endpoint(ctx: Context) {
    let data = process_request().await;

    ctx.set_response_status_code(200)
        .await
        .set_response_header(CONTENT_TYPE, APPLICATION_JSON)
        .await
        .set_response_body(serde_json::to_string(&data).unwrap())
